'use strict';
(()=>{
 const TOKEN_KEY='pokemon-party-admin-session',STATE_KEY='pokemon-party-admin-login';let config=null,tokens=null,tab='devices',pageTab='shares',deviceFilter='',panels={shares:{cursor:null,back:[],request:0},activity:{cursor:null,back:[],request:0}};
 const content=document.querySelector('#admin-content'),status=document.querySelector('#admin-status');
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=value=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(typeof value==='number'?value*1000:value)),p=Object.fromEntries(parts.map(v=>[v.type,v.value]));return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`;};
 const deviceBadge=id=>`<span class="admin-device-badge" title="${escape(id)}" aria-label="디바이스 ID ${escape(id)}">${escape(String(id).slice(0,8))}</span>`;
 const showStatus=(message='',error=false)=>{status.textContent=message;status.classList.toggle('error',error);};
 function loginView(message='초대 링크와 접속 기기를 관리하려면 로그인해 주세요.'){
  document.querySelector('.admin-header').hidden=true;document.querySelector('#admin-logout').hidden=true;content.innerHTML='<section class="admin-login"><svg class="admin-login-pikachu" role="img" aria-label="피카츄" width="128" height="128" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><title>피카츄</title><rect width="512" height="512" fill="#fff1b8"/><g stroke="#342b26" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"><path d="M159 224C128 189 103 118 106 58C154 82 180 131 193 204Z" fill="#ffda43"/><path d="M106 58C129 70 148 88 161 108L116 133C109 108 105 82 106 58Z" fill="#342b26" stroke="none"/><path d="M319 202C345 150 379 89 429 61C432 128 407 187 363 226Z" fill="#ffda43"/><path d="M429 61C430 88 426 116 416 140L373 114C392 89 410 72 429 61Z" fill="#342b26" stroke="none"/><path d="M159 196C198 169 309 169 352 196C391 221 404 266 393 301L410 326C416 348 403 370 386 384C358 409 305 427 256 427C206 427 153 409 125 384C108 370 95 348 102 326L119 301C107 266 120 222 159 196Z" fill="#ffdf48"/><g stroke="none"><ellipse cx="149" cy="337" rx="28" ry="30" fill="#ef4745"/><ellipse cx="365" cy="337" rx="28" ry="30" fill="#ef4745"/><ellipse cx="202" cy="269" rx="20" ry="23" fill="#342b26"/><ellipse cx="310" cy="269" rx="20" ry="23" fill="#342b26"/><circle cx="197" cy="262" r="7" fill="#fff"/><circle cx="305" cy="262" r="7" fill="#fff"/><path d="M246 304Q256 299 266 304L256 314Z" fill="#342b26"/></g><path d="M228 337Q242 350 256 336Q270 350 284 337" fill="none" stroke-width="8"/></g></svg><h2>관리자 로그인</h2><p id="admin-login-note"></p><button class="admin-button primary" id="admin-login">로그인</button></section>';
  document.querySelector('#admin-login-note').textContent=message;document.querySelector('#admin-login').disabled=!config?.admin?.clientId;
 }
 const urlSafe=bytes=>btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
 async function login(){
  const verifier=urlSafe(crypto.getRandomValues(new Uint8Array(48))),state=urlSafe(crypto.getRandomValues(new Uint8Array(32))),challenge=urlSafe(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))));
  sessionStorage.setItem(STATE_KEY,JSON.stringify({state,verifier,created:Date.now()}));
  const url=new URL('/oauth2/authorize',config.admin.loginOrigin);url.search=new URLSearchParams({client_id:config.admin.clientId,response_type:'code',scope:'openid email profile',redirect_uri:config.admin.redirectUri,state,code_challenge:challenge,code_challenge_method:'S256'});location.assign(url.href);
 }
 async function tokenRequest(parameters){
  const response=await fetch(new URL('/oauth2/token',config.admin.loginOrigin),{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:config.admin.clientId,...parameters})});const result=await response.json();if(!response.ok||!result.access_token)throw Error('로그인을 확인하지 못했어요. 다시 로그인해 주세요.');
  tokens={access:result.access_token,refresh:result.refresh_token||tokens?.refresh,expires:Date.now()+result.expires_in*1000};sessionStorage.setItem(TOKEN_KEY,JSON.stringify(tokens));
 }
 async function api(path,options={}){
  if(!tokens)throw Error('로그인이 필요합니다.');if(tokens.expires<Date.now()+30000&&tokens.refresh)await tokenRequest({grant_type:'refresh_token',refresh_token:tokens.refresh});
  const response=await fetch(path,{...options,cache:'no-store',headers:{authorization:'Bearer '+tokens.access,...(options.body?{'content-type':'application/json'}:{}),...options.headers}});const data=await response.json();if(!response.ok){if(response.status===401||data.reason==='admin_required'){tokens=null;sessionStorage.removeItem(TOKEN_KEY);loginView();}throw Error(data.error||'요청을 완료하지 못했어요.');}return data;
 }
 function shareRow(row){
  const expired=row.expiresAt*1000<=Date.now(),state=row.status==='revoked'?'revoked':expired?'expired':'active',label=state==='revoked'?'사용 중지':expired?'기간 만료':'사용 가능';
  return `<article class="admin-row"><div class="admin-row-info"><h3>${escape(row.label||'파티 초대 링크')}<span class="admin-badge ${state}">${label}</span></h3><p>만료: ${date(row.expiresAt)} · 발급 기기 ${row.claimCount}대</p><p>생성: ${date(row.createdAt)}</p></div><div class="admin-row-actions"><button class="admin-button" data-copy="${escape(row.url)}" ${state!=='active'?'disabled':''}>링크 복사</button><button class="admin-button danger" data-share-revoke="${row.shareId}" ${state!=='active'?'disabled':''}>사용 중지</button><button class="admin-button danger" data-share-delete="${row.shareId}">삭제</button></div></article>`;
 }
 function deviceRow(row){
  const blocked=row.status!=='active';return `<article class="admin-row"><div class="admin-row-info"><h3>${escape(row.trainerName||'이름 입력 전')}${deviceBadge(row.deviceId)}<span class="admin-badge ${blocked?'blocked':''}">${blocked?'차단됨':'사용 가능'}</span></h3><p>최근 접속: ${date(row.lastSeenAt)} · ${row.visitCount||0}회</p><p>첫 접속: ${date(row.createdAt)}</p><p>${escape(row.userAgent||'브라우저 정보 없음')}</p></div><div class="admin-row-actions"><button class="admin-button" data-device-visits="${row.deviceId}">접속 기록</button><button class="admin-button ${blocked?'':'danger'}" data-device-state="${row.deviceId}" data-action="${blocked?'unblock':'block'}">${blocked?'차단 해제':'차단'}</button><button class="admin-button danger" data-device-delete="${row.deviceId}">삭제</button></div></article>`;
 }
 const visitRow=row=>`<article class="admin-row"><div class="admin-row-info"><div class="admin-visit-heading"><h3>${escape(row.trainerName||'이름 입력 전')}${deviceBadge(row.deviceId)}</h3><time datetime="${escape(row.createdAt)}">${date(row.createdAt)}</time></div><p>(${escape(row.userAgent||'브라우저 정보 없음')})</p></div></article>`;
 function selectPage(page){pageTab=page;document.querySelectorAll('[data-admin-page]').forEach(b=>{const selected=b.dataset.adminPage===page;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));});document.querySelector('#shares-panel').hidden=page!=='shares';document.querySelector('#activity-panel').hidden=page!=='activity';}
 function dashboard(){
  document.querySelector('.admin-header').hidden=false;document.querySelector('#admin-logout').hidden=false;content.innerHTML='<div class="admin-page-tabs" role="tablist" aria-label="관리 메뉴"><button class="admin-button" role="tab" id="shares-tab" data-admin-page="shares" aria-controls="shares-panel">초대 링크</button><button class="admin-button" role="tab" id="activity-tab" data-admin-page="activity" aria-controls="activity-panel">접속 관리</button></div><section class="admin-card" id="shares-panel" role="tabpanel" aria-labelledby="shares-tab"><div class="admin-panel-heading"><h2>파티 초대 링크</h2></div><p>링크는 만든 뒤 3일 동안 사용할 수 있어요. 발급된 기기 키는 자동 만료 없이 유지됩니다.</p><form id="share-create" class="admin-create"><input id="share-label" aria-label="초대 링크 이름" placeholder="링크 이름 (선택)" maxlength="60"><button class="admin-button primary" type="submit">초대 링크 만들기</button></form><div class="share-output" id="share-output" hidden><p>초대 링크를 복사해서 친구에게 전해 주세요.</p><div class="share-copy"><input id="new-share-url" aria-label="새 초대 링크" readonly><button class="admin-button" id="copy-new-share">복사</button></div></div><div class="admin-list admin-share-list" id="shares-list"></div><div class="admin-pager"><button class="admin-button" data-panel-prev="shares" hidden>이전</button><button class="admin-button" data-panel-next="shares" hidden>다음</button></div></section><section class="admin-card" id="activity-panel" role="tabpanel" aria-labelledby="activity-tab"><div class="admin-panel-heading"><h2>접속 기기와 기록</h2></div><div class="admin-tabs"><button class="admin-button active" data-admin-tab="devices">접속 기기</button><button class="admin-button" data-admin-tab="visits">접속 기록</button></div><div class="admin-visit-filter" id="visit-filter" hidden></div><div class="admin-list" id="admin-list"></div><div class="admin-pager"><button class="admin-button" data-panel-prev="activity" hidden>이전</button><button class="admin-button" data-panel-next="activity" hidden>다음</button></div></section>';
  showStatus();selectPage(pageTab);loadList(pageTab);
 }
 async function loadList(panel){
  const state=panels[panel],request=++state.request,kind=panel==='shares'?'shares':tab,list=document.querySelector(panel==='shares'?'#shares-list':'#admin-list');if(!list)return;
  if(panel==='activity'){document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));const filter=document.querySelector('#visit-filter');filter.hidden=tab!=='visits'||!deviceFilter;filter.innerHTML=filter.hidden?'':`<span>${deviceBadge(deviceFilter)} 접속 기록</span><button class="admin-button" id="all-visits">전체 기록</button>`;}
  list.innerHTML='<p class="admin-empty">기록을 불러오고 있어요.</p>';document.querySelectorAll(`[data-panel-prev="${panel}"],[data-panel-next="${panel}"]`).forEach(b=>b.disabled=true);
  const params=new URLSearchParams();if(state.cursor)params.set('cursor',state.cursor);if(kind==='visits'&&deviceFilter)params.set('deviceId',deviceFilter);
  const query=params.toString();
  try{const data=await api('/api/admin/'+kind+(query?'?'+query:''));if(state.request!==request||!list.isConnected)return;list.innerHTML=data.items.length?data.items.map(kind==='shares'?shareRow:kind==='devices'?deviceRow:visitRow).join(''):`<p class="admin-empty">${data.nextCursor?'이 구간에는 기록이 없어요. 다음 기록도 살펴볼까요?':'아직 기록이 없어요.'}</p>`;document.querySelector(`[data-panel-prev="${panel}"]`).hidden=!state.back.length;const next=document.querySelector(`[data-panel-next="${panel}"]`);next.hidden=!data.nextCursor;next.dataset.cursor=data.nextCursor||'';
  }catch(error){if(state.request===request&&list.isConnected){list.innerHTML='<p class="admin-empty"></p>';list.firstElementChild.textContent=error.message;}}
  finally{if(state.request===request)document.querySelectorAll(`[data-panel-prev="${panel}"],[data-panel-next="${panel}"]`).forEach(b=>b.disabled=false);}
 }
 async function copy(text){try{await navigator.clipboard.writeText(text);showStatus('초대 링크를 복사했어요.');}catch{showStatus('링크를 선택해서 복사해 주세요.');const field=document.querySelector('#new-share-url');if(field){field.value=text;document.querySelector('#share-output').hidden=false;field.focus();field.select();}}}
 async function mutation(path,method,body){showStatus('변경하고 있어요.');try{await api(path,{method,body:body?JSON.stringify(body):undefined});if(method==='DELETE'&&path.endsWith('/'+document.querySelector('#share-output')?.dataset.shareId)){document.querySelector('#share-output').hidden=true;document.querySelector('#new-share-url').value='';}await loadList(path.includes('/shares/')?'shares':'activity');showStatus();}catch(error){showStatus(error.message,true);}}
 document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;b.blur();
  if(b.id==='admin-login'){login().catch(error=>showStatus(error.message,true));return;}
  if(b.id==='admin-logout'){tokens=null;sessionStorage.removeItem(TOKEN_KEY);const url=new URL('/logout',config.admin.loginOrigin);url.search=new URLSearchParams({client_id:config.admin.clientId,logout_uri:config.admin.redirectUri});location.assign(url.href);return;}
  if(b.dataset.adminPage){selectPage(b.dataset.adminPage);loadList(pageTab);return;}
  if(b.dataset.adminTab){deviceFilter='';tab=b.dataset.adminTab;panels.activity.cursor=null;panels.activity.back=[];loadList('activity');return;}
  if(b.dataset.panelNext){const panel=b.dataset.panelNext,state=panels[panel];state.back.push(state.cursor);state.cursor=b.dataset.cursor;loadList(panel);return;}
  if(b.dataset.panelPrev){const panel=b.dataset.panelPrev,state=panels[panel];state.cursor=state.back.pop();loadList(panel);return;}
  if(b.id==='copy-new-share'){copy(document.querySelector('#new-share-url').value);return;}if(b.dataset.copy){copy(b.dataset.copy);return;}
  if(b.dataset.deviceVisits){deviceFilter=b.dataset.deviceVisits;tab='visits';panels.activity.cursor=null;panels.activity.back=[];selectPage('activity');loadList('activity');return;}
  if(b.id==='all-visits'){deviceFilter='';panels.activity.cursor=null;panels.activity.back=[];loadList('activity');return;}
  if(b.dataset.deviceState){mutation('/api/admin/devices/'+b.dataset.deviceState,'PATCH',{action:b.dataset.action});return;}
  if(b.dataset.deviceDelete&&confirm('이 기기의 초대장을 삭제할까요? 다시 접속하려면 초대 링크가 필요합니다.')){mutation('/api/admin/devices/'+b.dataset.deviceDelete,'DELETE');return;}
  if(b.dataset.shareDelete&&confirm('이 초대 링크를 영구 삭제할까요? 삭제한 링크는 복구할 수 없으며, 이미 발급된 기기 키는 유지됩니다.')){mutation('/api/admin/shares/'+b.dataset.shareDelete,'DELETE');return;}
  if(b.dataset.shareRevoke&&confirm('이 링크의 사용을 중지할까요? 이미 발급된 기기 키는 계속 사용할 수 있습니다.'))mutation('/api/admin/shares/'+b.dataset.shareRevoke,'PATCH',{action:'revoke'});
 });
 document.addEventListener('focusin',event=>{if(event.target.matches('button'))event.target.blur();});
 document.addEventListener('submit',async event=>{if(event.target.id!=='share-create')return;event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;showStatus('초대 링크를 만들고 있어요.');try{const result=await api('/api/admin/shares',{method:'POST',body:JSON.stringify({label:document.querySelector('#share-label').value})});document.querySelector('#share-output').hidden=false;document.querySelector('#share-output').dataset.shareId=result.share.shareId;document.querySelector('#new-share-url').value=result.share.url;panels.shares.cursor=null;panels.shares.back=[];await loadList('shares');showStatus();}catch(error){showStatus(error.message,true);}finally{button.disabled=false;}});
 (async()=>{try{const response=await fetch('/api/access/config',{cache:'no-store'});if(!response.ok)throw Error('관리자 설정을 확인하지 못했어요.');config=await response.json();const params=new URLSearchParams(location.search),code=params.get('code');
   if(code){const pending=JSON.parse(sessionStorage.getItem(STATE_KEY)||'null');sessionStorage.removeItem(STATE_KEY);history.replaceState(null,'','/admin');if(!pending||pending.state!==params.get('state')||Date.now()-pending.created>600000)throw Error('로그인 요청을 확인하지 못했어요. 다시 로그인해 주세요.');await tokenRequest({grant_type:'authorization_code',code,redirect_uri:config.admin.redirectUri,code_verifier:pending.verifier});}
   else{try{tokens=JSON.parse(sessionStorage.getItem(TOKEN_KEY)||'null');}catch{tokens=null;}}
   if(tokens){dashboard();}else{loginView(config.admin.clientId?undefined:'관리자 로그인을 준비하고 있어요.');showStatus();}
  }catch(error){loginView(error.message);showStatus(error.message,true);}})();
})();
